const input = $input.first().json;
const evidencePack = input.evidence_pack || {};
const snapshot = input.snapshot || {};
const skills = input.skills || [];
const prompt = input.prompt || '';

const systemPrompt = `Eres un abogado especialista en propiedad industrial e intelectual en España y la Unión Europea.
Genera un informe profesional de IP basándote EXCLUSIVAMENTE en las evidencias aportadas.

REGLAS DE CITACIÓN:
- CITA cada afirmación factual usando [SRC-XXX]
- NO inventes fuentes ni datos
- Si no tienes evidencia, indica "No consta en las evidencias aportadas"
- URLs solo de oepm.es, euipo.europa.eu o wipo.int

SECCIONES OBLIGATORIAS:
1. TITULAR — Datos del titular de los derechos IP
2. MATRIZ DE MARCAS — Tabla con todas las marcas, clases Niza, estado, jurisdicción
3. DIAGNÓSTICO — Vencimientos próximos, gaps de cobertura, incoherencias titularidad
4. RECOMENDACIONES — Acciones prioritarias, renovaciones, extensiones`;

let skillInstructions = '';
for (const s of skills) {
  skillInstructions += `\n--- Skill: ${s.skill_key} ---\n${s.prompt_template || s.prompt || ''}\n`;
}

const userPrompt = `${prompt}\n${skillInstructions}\n\nEVIDENCE PACK:\n${JSON.stringify(evidencePack, null, 2)}\n\nSNAPSHOT IP:\n${JSON.stringify(snapshot, null, 2)}`;

return [{
  json: {
    report_id: input.report_id,
    request_id: input.request_id,
    system_prompt: systemPrompt,
    user_prompt: userPrompt,
    evidence_pack: evidencePack,
    model: 'default'
  }
}];

const harveyResponse = $input.first().json;
const prevData = $('Prepare IP Prompt').first().json;

const output = {
  report_id: prevData.report_id,
  request_id: prevData.request_id,
  output: {
    raw_response: harveyResponse.text || harveyResponse.completion || JSON.stringify(harveyResponse),
    model_used: harveyResponse.model || 'harvey-default',
    generated_at: new Date().toISOString(),
    evidence_pack_version: '1.1',
    sections: {
      titular: 'See raw_response',
      matriz_marcas: 'See raw_response',
      diagnostico: 'See raw_response',
      recomendaciones: 'See raw_response'
    }
  },
  status: 'ok'
};

return [{ json: output }];
